-- ContosoBikesDW: the Contoso Bikes star schema of episode 1, as a SQL Server database (generated by tools/make_sql.py, do not edit).
-- The aggregation grain of the model's Sales Agg table: Order Date x Product x Store.
USE [ContosoBikesDW];
GO
CREATE OR ALTER VIEW dbo.vwSalesAgg AS
SELECT f.OrderDate, f.ProductKey, f.StoreKey,
       CAST(SUM(f.Quantity) AS int) AS Units,
       CAST(SUM(f.LineAmount) AS decimal(18,2)) AS LineAmount,
       CAST(SUM(f.LineCost) AS decimal(18,2)) AS LineCost,
       COUNT_BIG(*) AS OrderLines
FROM dbo.FactSales AS f
GROUP BY f.OrderDate, f.ProductKey, f.StoreKey;
GO
